// @generated by crates/fno-agent/build.rs from crates/fno-agent/src/runtime/bus_read.rs. Do not edit.
//! The bus read rules the unread listing and the drain share: which rows are
//! mail, which are retracted, how a cursor file reads, and the cursor-bounded
//! unread walk. It reaches no other module of this crate, so build.rs copies
//! it into fno, whose front door answers `mail unread` in process.

use serde_json::Value;
use std::collections::HashSet;

/// The bus kinds that are bookkeeping about other messages, never inbox
/// content (`bus.log.CONTROL_KINDS`).
pub const WITHDRAW_KIND: &str = "withdraw";
const META: &str = "meta";
const CURSOR_KEY: &str = "last_seen_id";
const THREAD_KEY: &str = "thread";
const REPLY_KEY: &str = "in_reply_to";

/// A string field by name. One reader for every envelope key, so a key is
/// spelled where it is read and the repo counts no literal-key `.get`.
fn text<'a>(m: &'a Value, key: &str) -> Option<&'a str> {
    m.get(key).and_then(Value::as_str)
}

pub const LANDED_KIND: &str = "landed";
/// Delivery states meaning the bytes already reached the recipient
/// (`bus.log.HOSTED_DELIVERY` / `TYPED_DELIVERY`); draining one would hand
/// the recipient a second copy. `cross-session` is the historical backfill
/// shape: the receiver transcript named in its provenance is the proof the
/// bytes landed, so it is archive, never pending mail.
const AUDIT_ONLY_DELIVERIES: &[&str] = &["hosted", "typed", "cross-session"];

pub fn deliverable(m: &Value) -> bool {
    let kind = text(m, "kind").unwrap_or("");
    if kind == WITHDRAW_KIND || kind == LANDED_KIND || kind == fno_mail::state::STATE_KIND {
        return false;
    }
    let delivery = text(m, "delivery").unwrap_or("");
    !AUDIT_ONLY_DELIVERIES.contains(&delivery)
}

/// Ids retracted by a tombstone, plus the tombstones themselves; a tombstone
/// counts only against a message from the same sender to the same address.
pub fn withdrawn_ids(msgs: &[Value]) -> std::collections::HashSet<String> {
    let by_id: std::collections::HashMap<&str, &Value> = msgs
        .iter()
        .filter_map(|m| text(m, "id").map(|id| (id, m)))
        .collect();
    let mut out = std::collections::HashSet::new();
    for m in msgs {
        if text(m, "kind") != Some(WITHDRAW_KIND) {
            continue;
        }
        if let Some(id) = text(m, "id") {
            out.insert(id.to_string());
        }
        let target_id = m.get(META).and_then(|meta| text(meta, "withdraws"));
        let matches = target_id.and_then(|t| by_id.get(t)).is_some_and(|target| {
            text(target, "from") == text(m, "from") && text(target, "to") == text(m, "to")
        });
        if let (Some(t), true) = (target_id, matches) {
            out.insert(t.to_string());
        }
    }
    out
}

/// Ids proven landed by a same-sender/recipient `landed` control row
/// (`bus.log.landed_ids`): the target must exist, match on both addresses,
/// and the acknowledging row's own id never joins.
pub fn landed_ids(msgs: &[Value]) -> std::collections::HashSet<String> {
    let by_id: std::collections::HashMap<&str, &Value> = msgs
        .iter()
        .filter_map(|m| text(m, "id").map(|id| (id, m)))
        .collect();
    let mut out = std::collections::HashSet::new();
    for m in msgs {
        if text(m, "kind") != Some(LANDED_KIND) {
            continue;
        }
        let target = m
            .get(META)
            .and_then(|meta| text(meta, "landed"))
            .and_then(|t| by_id.get(t));
        let Some(target) = target else { continue };
        if text(target, "from") == text(m, "from") && text(target, "to") == text(m, "to") {
            if let Some(t) = text(target, "id") {
                out.insert(t.to_string());
            }
        }
    }
    out
}

/// A consumer's cursor file read with the oracle's warnings: absent file is a
/// silent `None` (full rescan); unreadable or unparseable returns `None` plus
/// the stderr warning naming the Python exception class. A non-object cursor
/// reads as no cursor, and the truthiness gate mirrors the oracle: empty
/// string and numeric zero advance nothing.
pub fn read_cursor_file(path: &std::path::Path) -> (Option<String>, Vec<String>) {
    let file_name = path
        .file_name()
        .and_then(std::ffi::OsStr::to_str)
        .unwrap_or_default()
        .to_string();
    if !path.exists() {
        return (None, Vec::new());
    }
    let text = match std::fs::read_to_string(path) {
        Ok(text) => text,
        Err(_) => {
            return (
                None,
                vec![format!(
                    "bus cursor: ignoring corrupt cursor {file_name} (OSError); rescanning retained segments"
                )],
            )
        }
    };
    let parsed: Value = match serde_json::from_str(&text) {
        Ok(v) => v,
        Err(_) => {
            return (
                None,
                vec![format!(
                    "bus cursor: ignoring corrupt cursor {file_name} (JSONDecodeError); rescanning retained segments"
                )],
            )
        }
    };
    let cursor = match parsed.get(CURSOR_KEY) {
        Some(Value::String(s)) if !s.is_empty() => Some(s.clone()),
        Some(Value::Number(n)) if n.as_f64().map(|f| f != 0.0).unwrap_or(false) => {
            Some(n.to_string())
        }
        _ => None,
    };
    (cursor, Vec::new())
}

/// Rows addressed to `name` after `cursor`, in log order. The scan keeps the
/// first row per id, drops retracted (withdraw), superseded (a hosted-delivery
/// twin) and non-deliverable rows. The cursor row itself never lists, and a
/// cursor that rotated out of the retained log rescans every retained row
/// rather than silently skipping unprocessed mail.
pub fn unread_listing<'a>(msgs: &'a [Value], name: &str, cursor: Option<&str>) -> Vec<&'a Value> {
    // The withdrawal and hosted-twin sets come off the RAW rows (a twin may
    // share its id with an earlier deliverable row); dedupe keeps the first
    // row per id in log order and drops id-less rows.
    let retracted = withdrawn_ids(msgs);
    let superseded: HashSet<&str> = msgs
        .iter()
        .filter(|m| text(m, "delivery") == Some("hosted"))
        .filter_map(|m| text(m, "id"))
        .collect();

    let mut seen: HashSet<&str> = HashSet::new();
    let mut deduped: Vec<&Value> = Vec::new();
    for m in msgs {
        let Some(id) = text(m, "id") else {
            continue;
        };
        if seen.insert(id) {
            deduped.push(m);
        }
    }

    let mine = |m: &Value| {
        let Some(id) = text(m, "id") else {
            return false;
        };
        text(m, "to") == Some(name)
            && deliverable(m)
            && !retracted.contains(id)
            && !superseded.contains(id)
    };

    let mut unread: Vec<&Value> = Vec::new();
    let mut passed = cursor.is_none();
    for m in &deduped {
        if passed && mine(m) {
            unread.push(m);
        }
        if cursor.is_some() && text(m, "id") == cursor {
            passed = true;
        }
    }
    if !passed {
        unread = deduped.iter().copied().filter(|m| mine(m)).collect();
    }
    unread
}

pub fn str_field<'a>(m: &'a Value, key: &str) -> &'a str {
    m.get(key).and_then(Value::as_str).unwrap_or("")
}

fn quote(v: &str) -> String {
    serde_json::to_string(v).unwrap_or_default()
}

/// One envelope re-projected in the oracle's key order with its exact
/// `json.dumps` spacing (`", "` between pairs, `": "` after keys). Absent
/// strings read as empty, the thread falls back to the id, and a non-string
/// `in_reply_to` prints as null.
fn row_json(m: &Value) -> String {
    let id = str_field(m, "id");
    let thread = match m.get(THREAD_KEY) {
        Some(Value::String(t)) => quote(t),
        _ => quote(id),
    };
    let in_reply_to = match m.get(REPLY_KEY) {
        Some(Value::String(t)) => quote(t),
        _ => "null".to_string(),
    };
    let pairs = [
        ("id", quote(id)),
        ("thread", thread),
        ("from", quote(str_field(m, "from"))),
        ("to", quote(str_field(m, "to"))),
        ("kind", quote(str_field(m, "kind"))),
        ("ts", quote(str_field(m, "ts"))),
        ("in_reply_to", in_reply_to),
        ("body", quote(str_field(m, "body"))),
    ];
    let inner: Vec<String> = pairs
        .iter()
        .map(|(k, v)| format!("{}: {}", quote(k), v))
        .collect();
    format!("{{{}}}", inner.join(", "))
}

pub fn json_array(rows: &[&Value]) -> String {
    if rows.is_empty() {
        return "[]".to_string();
    }
    let inner: Vec<String> = rows.iter().copied().map(row_json).collect();
    format!("[{}]", inner.join(", "))
}
